import ua.ember.*;
public final class CoreTest {
 private static int passed;private static void test(boolean b,String text){if(!b)throw new AssertionError(text);passed++;System.out.println("PASS "+text);}
 private static EffectEngine.Step step(int color,int duration,String trigger){EffectEngine.Step s=new EffectEngine.Step();s.color=color;s.durationMs=duration;s.trigger=trigger;return s;}
 public static void main(String[] args){EffectEngine e=new EffectEngine();EffectEngine.Step a=step(0xff0000,1000,"timer"),b=step(0x0000ff,1000,"timer");b.transition="fade";e.start(new EffectEngine.Step[]{a,b},false,0);test(e.sample(1.5,false,null)==0x800080,"fade midpoint");test(e.sample(2.1,false,null)==0x0000ff&&!e.running,"one-shot final color");a.trigger="musicBeat";a.beatCount=2;e.start(new EffectEngine.Step[]{a,b},false,0);e.sample(.5,true,null);e.sample(1.1,true,null);test(e.index==0,"early beats ignored");e.sample(1.3,true,null);test(e.index==1,"counted beat gate");a.trigger="manual";e.start(new EffectEngine.Step[]{a,b},false,0);e.next();e.sample(.5,false,null);test(e.index==0,"manual minimum interval");e.sample(1.1,false,null);test(e.index==1,"queued manual request");a.trigger="musicSilence";a.thresholdDb=-40;a.holdMs=500;e.start(new EffectEngine.Step[]{a,b},false,0);e.sample(5,false,null);test(e.index==0,"missing audio is not silence");EffectEngine.Signal silence=new EffectEngine.Signal();e.sample(5.1,false,silence);e.sample(5.3,false,silence);e.sample(5.5,false,silence);e.sample(5.7,false,silence);test(e.index==1,"continuous silence hold");a.trigger="musicBeatOrTimer";a.timeoutMs=1000;e.start(new EffectEngine.Step[]{a,b},false,0);e.sample(1.5,false,null);test(e.index==0,"timeout follows minimum");e.sample(2.1,false,null);test(e.index==1,"timeout fallback");e.start(new EffectEngine.Step[]{b,b},true,0);e.pause(.5);e.sample(10,false,null);test(e.index==0,"pause freezes timeline");e.resume(10);e.sample(10.6,false,null);test(e.index==1,"resume preserves interval");test(hex(LedProtocol.color(0xff5a1f)).equals("7E070503FF5A1F10EF"),"RGB packet");test(hex(LedProtocol.mode(138,2)).equals("7E05038A03FFFF00EF"),"BLEDDM mode packet");test(hex(LedProtocol.micMode(3)).equals("7E05038304FFFF00EF"),"native strip microphone mode");test(hex(LedProtocol.power(false,0)).equals("7E07040000000201EF"),"BLEDOB off packet");AudioAnalysis analysis=new AudioAnalysis();short[] pcm=new short[2048];for(int i=0;i<pcm.length;i++)pcm[i]=(short)(16384*Math.sin(2*Math.PI*1000*i/48000));EffectEngine.Signal signal=analysis.analyze(pcm,pcm.length,48000,0,0);test(Math.abs(signal.rms-.3535)<.01&&signal.peak<=.501,"phone output analyzer calibration");System.out.println("TOTAL "+passed);}
 private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02X",v&255));return s.toString();}
}
